def tarixiy_shaxs_info(message):
    chat_id = message.chat.id
    if message.text == 'Amir Temur':
        bot.send_message(chat_id,"*Amir Temur (1336–1405) — buyuk sarkarda, davlat arbobi va Temuriylar imperiyasining asoschisi bo‘lib, O‘rta Osiyo, Fors, Kavkaz, Hindiston va Kichik Osiyoning katta qismini qo‘l ostiga olgan. Samarqandda tug‘ilgan Temur bolaligidan harbiy mahorat va strategiyani o‘rgangan, 1370-yilda Movarounnahr hukmdori bo‘lib, keyinchalik ulkan imperiya barpo etgan. Uning harbiy yurishlari Anadoludan (1402-yilda Ankara jangi) Hindistongacha (1398-yilda Dehlining egallanishi) cho‘zilgan. Temur ma’muriyatda markazlashtirilgan tizimni joriy qilib, sug‘orish inshootlari, savdo yo‘llari va madaniy obidalarni rivojlantirdi. Samarqandni gullab-yashnagan madaniyat markaziga aylantirib, Registon maydoni, Bibi Xonim masjidi kabi me’moriy durdonalar qurdirdi. Uning davlati harbiy qudrat, ilm-fan va hunarmandchilikning uyg‘unligi bilan ajralib turdi. Temur 1405-yilda Xitoyga yurish boshlaganida vafot etdi, lekin uning merosi keyingi avlodlar, jumladan, Mirzo Ulug‘bek davrida davom ettirildi. Uning strategiyalari va boshqaruv usullari hozirgacha tadqiqot mavzusi bo‘lib, O‘zbekiston va butun Markaziy Osiyo madaniyati uchun milliy qahramon hisoblanadi.*", parse_mode="Markdown")
    elif message.text == 'Ismoil Safaviy':
        bot.send_message(chat_id, "*Ismoil Safaviy (1487–1524) — Safaviylar davlatining asoschisi va Eronning birinchi shohi bo‘lib, 1501-yilda 14 yoshida taxtga o‘tirgan. U shia islomini Eronning rasmiy dini deb e’lon qilib, mamlakatning diniy va siyosiy kimligini tubdan o‘zgartirdi. Ismoil Safaviy qizil bosh kiyim kiygan qizilboshlar deb atalgan sodiq harbiy kuchlarga tayangan holda O‘zbek xoni Shayboniyni 1510-yilda Marv jangida mag‘lub etdi va Movarounnahr ustidan nazoratni qo‘lga kiritishga urindi. Uning hukmronligi davrida Eronda markazlashgan boshqaruv tizimi shakllandi, madaniyat va san’at, ayniqsa miniatyura va me’morchilik rivojlandi. Ismoil she’riyat bilan shug‘ullangan va “Xatoiy” taxallusi bilan turkiy va fors tillarida asarlar yozgan. 1514-yilda Chaldiron jangida Usmonli sultoni Salim I ga mag‘lub bo‘lishi uning kuchini pasaytirdi, ammo Safaviylar sulolasi 200 yildan ortiq hukmronlik qildi. Ismoil Safaviyning merosi Eronning shia musulmon davlati sifatida shakllanishida hal qiluvchi rol o‘ynadi va uning davri Eron tarixida yangi davr boshlanishi sifatida qaraladi.*", parse_mode="Markdown")
    elif message.text == 'Yovuz Sulton Salim':
       bot.send_message(chat_id, "*Yovuz Sulton Salim (1470–1520) Usmonlilar imperiyasining 9-sultoni boʻlib, 1512–1520 yillarda hukmronlik qilgan va 'Yovuz'(qattiq qoʻllik yoki qatʼiyatli) laqabi bilan mashhur boʻlgan. Uning hukmronligi davrida imperiya kengayib, markazlashtirildi. 1514-yilda Shoh Ismoil I Safaviyga qarshi Chaldiron jangida hal qiruvchi gʻalaba qozonib, Safaviylar qoʻshinini tor-mor qildi va Tabrizni egalladi, biroq uzoq muddat saqlab qololmadi. 1516–1517 yillarda Marj Dobiq va Ridoniya janglarida Misr mamluklarini magʻlub etib, Suriya, Falastin va Misrni Usmonlilar qoʻliga kiritdi, bu esa xalifalik unvonining Usmonli sultonlariga oʻtishiga olib keldi. U shiilar qirgʻini (1513–1514)ni amalga oshirib, 40–45 ming shia qatli qildi va sunniylikni rasmiy mazhab sifatida mustahkamladi. Hukmronligi davrida Usmonlilar hududi 70% ga oshib, 3,4 million km² ni tashkil etdi, Arabiston, Shimoliy Afrika va Kavkazga harbiy ekspeditsiyalar uyushtirdi. 1520-yilda Qohiradan Istanbulga qaytayotgan yoʻlda vafot etdi va uning yagona oʻgʻli Sulton Sulaymon I (Qonuniy) taxtga oʻtirdi. Yovuz Sulton Salimning harbiy islohotlari va maʼmuriy tizimi Usmonlilarni global qudvatga aylantirdi. Uning qabri Istanbulda joylashgan boʻlib, meʼmoriy jihatdan ajoyib bezatilgan, shuningdek, Istanbuldagi Salim koʻprigi (2016-yilda qurilgan) uning nomi bilan atalgan. Uning qatʼiy qarorlari va shafqatsizligi tufayli 'Yovuz' laqabini olgan.*" , parse_mode="Markdown")
    elif message.text == 'Mehmed Fotih':
        bot.send_message(chat_id, "*Mehmed Fotih (1432–1481) – Usmonli imperiyasining mashhur sultoni, Istanbulni egallab, Vizantiya imperiyasiga barham bergan davlat arbobi. U 1453-yil 21-yanvarda 21 yoshida taxtga oʻtirgan va shu yili Konstantinopolni qamal qilib, 53 kunlik qamaldan soʻng shaharni bosib olgan. Bu voqea tarixda oʻrta asrlarning tugashi va yangi davrning boshlanishi sifatida qayd etiladi. Mehmed Fotih nafaqat harbiy islohotlar, balki madaniyat, ilm-fan va maʼmuriy sohalarda ham katta yutuqlarga erishgan. Uning davrida Usmonli imperiyasi kuchayib, Yevropa va Osiyo oʻrtasidagi muhim hududlarni nazorat qila boshladi. Mehmed Fotih 'Fotih' (egallovchi) laqabini aynan Konstantinopolni egallagani uchun olgan. U zukko strateg, tilshunos va harbiy islohotchi sifatida tarixga kirdi. Mehmed Fotih 1481-yilda 49 yoshida vafot etdi, lekin uning merosi Usmonli imperiyasining kelajakdagi yuksalishiga asos soldi.", parse_mode="Markdown")
    elif message.text == 'Salohiddin Ayyubiy':
        bot.send_message(chat_id, "*Salohiddin Ayyubiy (1137–1193) musulmon dunyosining mashhur sarkardasi va davlat arbobi boʻlib, kurd oilasida Iroqning Tikrit shahrida tugʻilgan. Uning otasi Najmiddin Ayyub va amakisi Shirkuh Zangiylar sulolasi xizmatida harbiy qoʻmondonlar boʻlgan. Salohiddin Damashqda oʻsib, yaxshi diniy va harbiy taʼlim olgan. 1169-yilda amakisi Shirkuh vafot etgach, u Misrdagi Fatimiylar xalifaligiga vazir etib tayinlandi. 1171-yilda Fatimiylar hukmronligini tugatib, Misrni Sunniy Islomga qaytargan holda Ayyubiylar davlatiga asos soldi. 1187-yilda Hattin jangida salibchilar qoʻshinini tor-mor qilib, Quddusni 88 yillik salibchilar istilosidan ozod qildi. Bu gʻalaba musulmonlar orasida uning obroʻsini oshirdi. Uning ingliz qiroli Richard I (Arslon Yurak) bilan boʻlgan kurashi III salib yurishi davrida keng qamrovli janglarni oʻz ichiga oldi. Salohiddin nafaqat qobiliyatli sarkarda, balki dono davlat arbobi ham boʻlib, oʻz hukmronligi davrida Misr, Suriya, Yaman, Hijoz va Shimoliy Mesopotamiyani birlashtirgan. U adolatli boshqaruv tizimini joriy qilib, ilm-fan va madaniyatni qoʻllab-quvvatladi. Salohiddin 1193-yilda Damashqda vafot etdi va Umaviylar masjidi yonidagi qabriga dafn qilindi. Uning merosi nafaqat musulmonlar, balki salibchilar tomonidan ham yuqori baholangan. Salohiddin Ayyubiy insonparvarligi, jasorati va donoligi bilan tarixga katta iz qoldirdi.*", parse_mode="Markdown")
    elif message.text == 'Temur Malik':
        bot.send_message(chat_id, "*Temur Malik (XII asr oxiri—XIII asr boshlari) — Xorazmshoh Muhammad davridagi mashhur sarkarda va Xoʻjand hokimi boʻlib, moʻgʻullar istilosiga qarshi qatʼiy kurash olib borgan milliy qahramon hisoblanadi. 1219-yilda Chingizxon qoʻshinlari Xoʻjandni qamal qilganda, u Sirdaryo oʻrtasidagi orolda mustahkam qalʼa qurdirib, 1000 kishilik otryad bilan mudofaaga tayyorgarlik koʻrgan. Moʻgʻullar son jihatdan ustun boʻlib, 50 ming hasharchi yordamida daryo oqimini toʻsib, qalʼaga hujum qilishgan. Temur Malik ixtiro qilgan namat va sirkali loy bilan suvalgan kemalarda jang qilib, dushmanga ogʻir yoʻqotishlar yetkazgan. Biroq, qurollari tugagach, 70 qayiqda Sirdaryo boʻylab chekinishga majbur boʻlgan. Qizilqum choʻli orqali Xorazmga yetib kelib, Joʻjixon qoʻshiniga qarshi Kasba (Yangikent) shahrini ozod qilgan. Keyinchalik Jaloliddin Manguberdi safida 1221–1232 yillarda moʻgʻullarga qarshi kurashni davom ettirgan. Maʼlum vaqt oʻtgach, asirga olinib qatl etilgan. Uning jasorati haqida Mirmuhsin 'Temur Malik' romani (1986), Ashrafiy esa simfonik poema (1963) yaratgan. Rashiduddin, Bartold va Mirzo Ulugʻbek asarlarida uning faoliyati yoritilgan. Toshkentda uning nomi bilan koʻcha atalgan .")
    elif message.text == 'Horun ar_Rashid':
        bot.send_message(chat_id, "*Harun ar-Rashid (arabcha: هَارُون الرَشِيد, to‘liq ismi: Abū Jaʿfar Hārūn ibn Muḥammad al-Mahdī) 763-yilda Rey shahrida tug‘ilgan. U Abbosiylar xalifaligining beshinchi xalifasi bo‘lib, otasi al-Mahdi vafotidan so‘ng 786-yilda taxtga chiqdi. Harun ar-Rashid musulmon dunyosining eng kuchli hukmdorlaridan biri hisoblanadi. Uning davrida xalifalik G‘arbda Atlantika okeanidan to Sharqda Hind daryosigacha bo‘lgan keng hududni o‘z ichiga olgan.Harun ar-Rashid davrida Bag‘dod shahri Islom olamining madaniy va ilmiy markaziga aylangan. U 'Bayt al-Hikma' (arabcha: بيت الحكمة, ya'ni 'Donishmandlar uyi') ilmiy markazini tashkil qilgan bo‘lib, bu yerda yunon, hind va fors tillaridagi asarlar arab tiliga tarjima qilinardi. Matematiklar, tabiblar, faylasuflar va astronomlar bu markazda faoliyat yuritganlar. Ayniqsa, hind matematikasi va yunon falsafasi keng o‘rganilgan.Harun ar-Rashid san’at va adabiyot homiysi sifatida tanilgan. U ko‘plab shoirlar, yozuvchilar va olimlarni saroyiga yig‘gan. Unga bag‘ishlab yozilgan 'Ming bir kecha' (Arabcha: 'Alf layla wa layla') ertaklar to‘plami jahonga mashhur bo‘lib, unda Harun ar-Rashidning adolatli, zukko va ba’zan quvnoq obrazlari aks etgan.Xalifa G‘arb bilan ham faol diplomatik aloqalar olib borgan. Ayniqsa, u Franklar imperatori Karl Buyuk (Charlemagne) bilan maktub almashgan, hattoki unga qimmatbaho sovg‘alar yuborgan. Bu hodisa o‘sha davrda musulmonlar va nasroniylar o‘rtasida muvozanatli va hatto do‘stona munosabatlar mavjud bo‘lganini ko‘rsatadi.Harun ar-Rashid zamonida xalifalikda iqtisodiy yuksalish ham sodir bo‘lgan. Savdo yo‘llari kengaygan, ipak yo‘li orqali Xitoy bilan aloqalar rivojlangan. Soliqlar tizimi takomillashtirilgan, infratuzilma — yo‘llar, saroylar, masjidlar va hammomlar qurilgan.Harun ar-Rashid 809-yilda Tus shahrida vafot etgan. Uning o‘limidan so‘ng ikki o‘g‘li — Amin va Ma’mun o‘rtasida hokimiyat uchun kurash boshlanadi, bu esa xalifalikda siyosiy beqarorlik davrini boshlab bergan.Umuman olganda, Harun ar-Rashidning hukmronlik yillari Islom tarixida 'oltin davr' sifatida eslanadi. Bu davrda ilm-fan, madaniyat, iqtisod va siyosatda yuksalish yuz bergan bo‘lib, uning merosi hozirgi kungacha qadrlanadi.*", parse_mode="Markdown" )
    elif message.text == 'Abdulmalik ibn Marvon':
        bot.send_message(chat_id, "*Abdulmalik ibn Marvon (arabcha: عبد الملك بن مروان) — Umaviylar sulolasining eng muhim va islohotchi xalifalaridan biri bo‘lib, u milodiy 646-yilda Madina shahrida tug‘ilgan va 685–705-yillar oralig‘ida xalifalik qilgan. Abdulmalik o‘z davrida Umaviylar davlatini ichki parokandalikdan qutqarib, markazlashgan kuchli davlatga aylantirgan arbob sifatida tarixda muhim o‘rin egallaydi. U otasi Marvon I vafotidan keyin xalifa bo‘lgan. Bu davrda xalifalikda siyosiy beqarorlik hukm surgan, xususan Abdulloh ibn Zubayr Makka va Madina hududlarida o‘zini xalifa deb e'lon qilgan edi. Abdulmalik bu vaziyatni hal qilish uchun mashhur sarkarda Hajjaj ibn Yusufni yuborgan va 692-yilda Makka zabt etilib, Abdulloh ibn Zubayr o‘ldirilgan. Shu bilan xalifalik yana yagona markaziy hokimiyat ostida birlashtirilgan. Abdulmalik o‘z davrida ko‘plab islohotlarni amalga oshirgan. Eng muhim islohoti bu iqtisodiy mustaqillik edi — u musulmon dunyosida birinchi bo‘lib o‘z nomi bilan 'dinor' (oltin tanga) va 'dirham' (kumush tanga)larni zarb qilgan. Oldin Vizantiya yoki sosoniy tangalari ishlatilgan bo‘lsa, endi xalifalikda o‘ziga xos pul tizimi vujudga kelgan. Shuningdek, Abdulmalik davrida 'arablashtirish siyosati' boshlangan — ya’ni, davlat idoralari, soliqlar, hujjatlar va ma’muriy ish yurituv arab tiliga o‘tkazilgan. Bu butun xalifalik bo‘ylab madaniy va siyosiy birlashuvni ta’minlashga xizmat qilgan. Abdulmalik ibn Marvon me’morchilikka ham katta e’tibor bergan. Uning buyrug‘i bilan 691–692-yillarda Quddusda 'Qubbat as-Saxra' (arabcha: قبة الصخرة) qurilgan bo‘lib, bu inshoot islom me’morchiligidagi ilk yirik monumental binolardan biri hisoblanadi. Abdulmalik 705-yilda Damashqda vafot etgan va u o‘zidan keyin bir nechta o‘g‘illarini — xususan, al-Valid I va Sulaymon ibn Abdulmalikni xalifa etib qoldirgan. U boshqargan davr Umaviylar xalifaligini siyosiy, iqtisodiy va madaniy jihatdan mustahkamlagan davr bo‘lib, uning islohotlari islom tarixida chuqur iz qoldirgan.*", parse_mode="Markdown")
    elif message.text == 'Umar ibn Abdulaziz':
        bot.send_message(chat_id, "*Umar ibn Abdulaziz (arabcha: عمر بن عبد العزيز) — Umaviylar sulolasining sakkizinchi xalifasi bo‘lib, u 682-yilda tug‘ilgan va 717–720-yillar oralig‘ida xalifa bo‘lgan. U islom tarixida eng adolatli, dindor va xalqparvar xalifalardan biri sifatida tanilgan. Umar ibn Abdulaziz Madinada yetuk ilm olgan, fiqh, hadis va Qur’on ilmlarini chuqur o‘rgangan. U xalifa Sulaymon ibn Abdulmalik vafotidan so‘ng hokimiyatni qabul qilgan. Uning xalifalikka kelishi bilan Umaviylar davrida birinchi marta chinakam islohotlar boshlandi. U 'zulm', 'soliqlarni haddan oshirish', 'mansabdorlarning boylik orttirishi' kabi holatlarga qarshi qat’iy kurash olib borgan. Xalifalikka kelgan zahoti saroydagi ortiqcha boyliklarni davlat g‘aznasiga qaytargan, o‘z yaqinlarini mansablardan chetlashtirgan va kambag‘allarga yordam berishga katta e’tibor qaratgan. Unga qadar musulmon bo‘lmaganlardan olinadigan 'jizya' (soliq) musulmon bo‘lib kelsa ham to‘lovda davom ettirilardi, Umar ibn Abdulaziz esa bu odatni bekor qilib, islomni qabul qilgan har qanday kishidan 'jizya' undirmaslikni buyurdi. Bu tufayli xalifalikda ko‘plab xalqlar ommaviy ravishda islomga kirdi. U davlat xazinasini halol boshqargan, faqirlarni ro‘yxatga olib, ularni moddiy ta’minlashga harakat qilgan. Xalq orasida u 'ikkinchi Umar' yoki 'to‘rtinchi roshid xalifa' sifatida tanilgan. Uning davrida ilm-fan, adolat, din va inson huquqlari ustuvor bo‘lgan. Umar ibn Abdulaziz qisqa vaqt (taxminan 2,5 yil) hukmronlik qilgan bo‘lsa-da, u boshlab bergan siyosat va adolatli boshqaruv islom tarixida chuqur iz qoldirgan. U 720-yilda vafot etgan bo‘lib, ayrim manbalarga ko‘ra, siyosiy raqiblari tomonidan zaharlab o‘ldirilgan. Tarixchilar uning davrini 'xalifalik tarixidagi eng pok davr' deb baholaydilar.*", parse_mode="Markdown")
    elif message.text == 'Hunyadi Yanosh':
        bot.send_message(chat_id, "*Hunyadi Yanosh (1407–1456) — Vengriya va Transilvaniya tarixidagi eng mashhur sarkarda va davlat arboblaridan biri bo‘lib, u asosan Usmonli imperiyasiga qarshi olib borgan janglari bilan tanilgan. U asli valax zodagonlaridan bo‘lib, Transilvaniyada tug‘ilgan va keyinchalik Vengriya qirollik zodagonlari safiga kirgan. Hunyadi Yanosh o‘zining harbiy iste’dodi va siyosiy mahorati bilan tezda mashhurlikka erishgan. U 1441-yilda Transilvaniya voevodasi etib tayinlangan va bu lavozim orqali mintaqaning mudofaa ishlarini nazorat qilgan. Uning eng muhim harbiy xizmatlaridan biri 1443–1444-yillardagi 'Uzoq yurish' (Long Campaign) deb ataladigan harbiy yurish bo‘lib, u Usmonlilarga qarshi bir necha janglarda g‘alaba qozongan. Ammo 1444-yilda Varna jangida xristian koalitsiyasi yengilib, qirol Vladislav halok bo‘lgan. Shunga qaramay, Hunyadi Yanosh 1446-yilda Vengriya gubernatori etib tayinlandi va qirol yo‘qligida mamlakatni boshqara boshladi. U Vengriya armiyasini kuchaytirib, chegaralarni mustahkamladi va Usmonli bosqinlariga qarshi qat’iy siyosat yuritdi. 1456-yilda Belgrad qal’asi qamali chog‘ida Hunyadi Yanosh o‘zining eng katta g‘alabalaridan birini qo‘lga kiritdi — bu jang Usmonlilarning Yevropaga chuqur kirib kelishini vaqtincha to‘xtatdi. Shu g‘alaba xristian dunyosida keng nishonlandi, Papa Kaliks III esa har kuni 'belgrad g‘alabasi'ni eslab cherkov qo‘ng‘iroqlarini chalishni buyurdi — bu an’ana hozirgacha davom etib keladi. Afsuski, g‘alabadan ko‘p o‘tmay, Hunyadi Yanosh Belgradda vabo kasalligidan vafot etdi. Uning o‘g‘li Matyash Hunyadi keyinchalik Vengriya qiroli bo‘lgan. Hunyadi Yanosh xristian Yevropasini Usmonlilar bosqinidan himoya qilgan qahramon sifatida tarixda chuqur iz qoldirgan va bugungi kunda ham Vengriya milliy qahramoni sifatida yodga olinadi*",parse_mode="Markdown")
    elif message.text == '🔙Orqaga':
        bot.send_message(chat_id, "Quyidagilardan birini tanlang!", reply_markup=generate_main_menu())
